#!/usr/bin/env python3
"""Merge every audit artifact into one Markdown report for the run summary."""

from __future__ import annotations

import argparse
import os
from pathlib import Path

ORDER = [
    "checklist.md",
    "lint.md",
    "mobsfscan.md",
    "gitleaks.md",
    "mobsf.md",
    "a11y.md",
    "uiux.md",
    "apk.md",
]


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--input", default="audit-download")
    parser.add_argument("--out", default="audit-report/AUDIT.md")
    args = parser.parse_args()

    root = Path(args.input)
    out = Path(args.out)
    out.parent.mkdir(parents=True, exist_ok=True)

    found = {p.name: p for p in root.rglob("*.md")}
    sections = [
        "# ImanCore automated audit report",
        "",
        "Generated by `.github/workflows/ci.yml`. Sources: embedded audit checklist, "
        "Android Lint, CodeQL, mobsfscan (OWASP mobile static analysis), Gitleaks, MobSF APK "
        "security scan, device accessibility measurement, UI/UX exploratory audit and "
        "instrumented tests.",
        "",
    ]
    used: set[str] = set()
    for name in ORDER:
        if name in found:
            sections.append(found[name].read_text(encoding="utf-8", errors="replace").strip())
            sections.append("")
            used.add(name)
    for name, path in sorted(found.items()):
        if name not in used:
            sections.append(path.read_text(encoding="utf-8", errors="replace").strip())
            sections.append("")

    if not used and len(sections) <= 4:
        sections.append("_No audit artifacts were produced. Treat the run as UNVERIFIED._")

    report = "\n".join(sections) + "\n"
    out.write_text(report, encoding="utf-8")

    summary = os.environ.get("GITHUB_STEP_SUMMARY")
    if summary:
        with open(summary, "a", encoding="utf-8") as handle:
            handle.write(report)

    print(f"wrote {out} ({len(report)} bytes) from {len(found)} artifact(s)")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
